import{_ as n,w as a,s as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"如何備份一個磁盤分區 | LCTT x X-CMD","titleTemplate":false,"description":"如何備份一個磁盤分區 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何備份一個磁盤分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何備份一個磁盤分區 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170112 Partition Backup","title":"如何備份一個磁盤分區","tag":"201705","desc":""},"relativePath":"201705/20170112 Partition Backup.md","filePath":"[post].md"}'),e={name:"201705/20170112 Partition Backup.md"};function i(c,s,d,t,o,r){return a(),p("div",null,[...s[0]||(s[0]=[l('<h1 id="如何備份一個磁盤分區" tabindex="-1">如何備份一個磁盤分區 <a class="header-anchor" href="#如何備份一個磁盤分區" aria-label="Permalink to “如何備份一個磁盤分區”">​</a></h1><p>通常你可能會把數據放在一個分區上，有時候可能需要對該設備或者上面的一個分區進行備份。樹莓派用户為了可引導 SD 卡當然有這個需求。其它小體積計算機的用户也會發現這非常有用。有時候設備看起來要出現故障時最好快速做個備份。</p><p>進行本文中的實驗你需要一個叫 <code>dcfldd</code> 的工具。</p><h3 id="dcfldd-工具" tabindex="-1">dcfldd 工具 <a class="header-anchor" href="#dcfldd-工具" aria-label="Permalink to “dcfldd 工具”">​</a></h3><p>該工具是 coreutils 軟件包中 <code>dd</code> 工具的增強版。<code>dcfldd</code> 是 Nicholas Harbour 在美國國防部計算機取證實驗室（DCFL）工作期間研發的。該工具的名字也基於他工作的地方 - <code>dcfldd</code>。</p><p>對於仍然在使用 CoreUtils 8.23 或更低版本的系統，並沒有一個可以輕鬆查看正在創建副本的進度的選項。有時候看起來就像什麼都沒有發生，以至於你就想取消掉備份。</p><p><strong>注意：</strong>如果你使用 8.24 或更新版本的 <code>dd</code> 工具，你就不需要使用 <code>dcfldd</code>，只需要用 <code>dd</code> 替換 <code>dcfldd</code> 即可。所有其它參數仍然適用。</p><p>在 Debian 系統上你只需要在 Package Manager 中搜索 <code>dcfldd</code>。你也可以打開一個終端然後輸入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install dcfldd</span></span></code></pre></div><p>對於 Red Hat 系統，可以用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /tmp  </span></span>\n<span class="line"><span>wget dl.fedoraproject.org/pub/epel/6/i386/dcfldd-1.3.4.1-4.el6.i686.rpm  </span></span>\n<span class="line"><span>sudo yum install dcfldd-1.3.4.1-4.el6.i686.rpm  </span></span>\n<span class="line"><span>dcfldd --version</span></span></code></pre></div><p><strong>注意：</strong> 上面的命令安裝的是 32 位版本。對於 64 位版本，使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /tmp  </span></span>\n<span class="line"><span>wget dl.fedoraproject.org/pub/epel/6/x86_64/dcfldd-1.3.4.1-4.el6.x86_64.rpm  </span></span>\n<span class="line"><span>sudo yum install dcfldd-1.3.4.1-4.el6.x86_64.rpm  </span></span>\n<span class="line"><span>dcfldd --version</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>每組命令中的最後一個語句會列出 `dcfldd` 的版本並顯示該命令文件已經被加載。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：**確保你以 root 用户執行 `dd` 或者 `dcfldd` 命令。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>安裝完該工具後你就可以繼續使用它備份和恢復分區。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 備份分區</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>備份設備的時候可以備份整個設備也可以只是其中的一個分區。如果設備有多個分區，我們可以分別備份每個分區。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>在進行備份之前，先讓我們來看一下設備和分區的區別。假設我們有一個已經被格式化為一個大磁盤的 SD 卡。這個 SD 卡只有一個分區。如果空間被切分使得 SD 卡看起來是兩個設備，那麼它就有兩個分區。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>假設我們有一個樹莓派中的 SD 卡。SD 卡容量為 8 GB，有兩個分區。第一個分區存放 BerryBoot 啓動引導器。第二個分區存放 Kali（LCTT 譯註：Kali Linux 是一個 Debian 派生的 Linux 發行版）。現在已經沒有可用的空間用來安裝第二個操作系統。我們使用大小為 16 GB 的第二個 SD 卡，但拷貝到第二個 SD 卡之前，第一個 SD 卡必須先備份。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>要備份第一個 SD 卡我們需要備份設備 `/dev/sdc`。進行備份的命令如下所示：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd if=/dev/sdc of=/tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>備份包括輸入文件（`if`）以及被設置為 `/tmp` 目錄下名為 `SD-Card-Backup.img` 的輸出文件（`of`）。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>`dd` 和 `dcfldd` 默認都是每次讀寫文件中的一個塊。通過上述命令，它可以一次默認讀寫 512 個字節。記住，該複製是一個精準的拷貝 - 逐位逐字節。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>默認的 512 個字節可以通過塊大小參數 - `bs=` 更改。例如，要每次讀寫 1 兆字節，參數為 `bs=1M`。使用以下所用的縮寫可以設置不同大小：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>*   b – 512 字節</span></span>\n<span class="line"><span>*   KB – 1000 字節</span></span>\n<span class="line"><span>*   K – 1024 字節</span></span>\n<span class="line"><span>*   MB – 1000x1000 字節</span></span>\n<span class="line"><span>*   M – 1024x1024 字節</span></span>\n<span class="line"><span>*   GB – 1000x1000x1000 字節</span></span>\n<span class="line"><span>*   G – 1024x1024x1024 字節</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>你也可以單獨指定讀和寫的塊大小。要指定讀塊的大小使用 `ibs=`。要指定寫塊的大小使用 `obs=`。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>我使用三種不同的塊大小做了一個 120 MB 分區的備份測試。第一次使用默認的 512 字節，它用了 7 秒鐘。第二次塊大小為 1024 K，它用時 2 秒。第三次塊大小是 2048 K，它用時 3 秒。用時會隨系統以及其它硬件實現的不同而變化，但通常來説更大的塊大小會比默認的稍微快一點。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>完成備份後，你還需要知道如何把數據恢復到設備中。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 恢復分區</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>現在我們已經有了一個備份點，假設數據可能被損毀了或者由於某些原因需要進行恢復。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>命令和備份時相同，只是源和目標相反。對於上面的例子，命令會變為：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd of=/dev/sdc if=/tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>這裏，鏡像文件被用作輸入文件（`if`）而設備（sdc）被用作輸出文件（`of`）。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：** 要記住輸出設備會被重寫，它上面的所有數據都會丟失。通常來説在恢復數據之前最好用 GParted 刪除 SD 卡上的所有分區。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>假如你在使用多個 SD 卡，例如多個樹莓派主板，你可以一次性寫多塊 SD 卡。為了做到這點，你需要知道系統中卡的 ID。例如，假設我們想把鏡像 `BerryBoot.img` 拷貝到兩個 SD 卡。SD 卡分別是 `/dev/sdc` 和 `/dev/sdd`。下面的命令在顯示進度時每次讀寫 1 MB 的塊。命令如下：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd if=BerryBoot.img bs=1M status=progress | tee &gt;(dcfldd of=/dev/sdc) | dcfldd of=/dev/sdd</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>在這個命令中，第一個 `dcfldd` 指定輸入文件並把塊大小設置為 1 MB。`status` 參數被設置為顯示進度。然後輸入通過管道 `|`傳輸給命令 `tee`。`tee` 用於將輸入分發到多個地方。第一個輸出是到命令 `dcfldd of=/dev/sdc`。命令被放到小括號內被作為一個命令執行。我們還需要最後一個管道 `|`，否則命令 `tee` 會把信息發送到 `stdout` （屏幕）。因此，最後的輸出是被髮送到命令  `dcfldd of=/dev/sdd`。如果你有第三個 SD 卡，甚至更多，只需要添加另外的重定向和命令，類似 `&gt;(dcfldd of=/dev/sde`。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：**記住最後一個命令必須在管道 `|` 後面。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>必須驗證寫的數據確保數據是正確的。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 驗證數據</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>一旦創建了一個鏡像或者恢復了一個備份，你可以驗證這些寫入的數據。要驗證數據，你會使用名為 `diff` 的另一個不同程序。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>使用 `diff` ，你需要指定鏡像文件的位置以及系統中拷貝自或寫入的物理媒介。你可以在創建備份或者恢復了一個鏡像之後使用 `diff` 命令。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>該命令有兩個參數。第一個是物理媒介，第二個是鏡像文件名稱。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>對於例子 `dcfldd of=/dev/sdc if=/tmp/SD-Card-Backup.img`，對應的 `diff` 命令是：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>diff /dev/sdc /tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>如果鏡像和物理設備有任何的不同，你會被告知。如果沒有顯示任何信息，那麼數據就驗證為完全相同。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>確保數據完全一致是驗證備份和恢復完整性的關鍵。進行備份時需要注意的一個主要問題是鏡像大小。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>### 分割鏡像</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>假設你想要備份一個 16GB 的 SD 卡。鏡像文件大小會大概相同。如果你只能把它備份到 FAT32 分區會怎樣呢？FAT32 最大文件大小限制是 4 GB。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>必須做的是文件必須被切分為 4 GB 的分片。通過管道 `|` 將數據傳輸給 `split` 命令可以切分正在被寫的鏡像文件。 </span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>創建備份的方法相同，但命令會包括管道和切分命令。示例備份命令為 `dcfldd if=/dev/sdc of=/tmp/SD-Card-Backup.img` ，其切分文件的新命令如下：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>dcfldd if=/dev/sdc | split -b 4000MB - /tmp/SD-Card-Backup.img</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**注意：** 大小後綴和對 `dd` 及 `dcfldd` 命令的意義相同。 `split` 命令中的破折號用於將通過管道從 `dcfldd` 命令傳輸過來的數據填充到輸入文件。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>文件會被保存為 `SD-Card-Backup.imgaa` 和 `SD-Card-Backup.imgab`，如此類推。如果你擔心文件大小太接近 4 GB 的限制，可以試着用 3500MB。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>將文件恢復到設備也很簡單。你使用 `cat` 命令將它們連接起來然後像下面這樣用 `dcfldd` 寫輸出：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>cat /tmp/SD-Card-Backup.img* | dcfldd of=/dev/sdc</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>你可以在命令中 `dcfldd` 部分包含任何需要的參數。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>我希望你瞭解並能執行任何需要的數據備份和恢復，正如 SD 卡和類似設備所需的那樣。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>--------------------------------------------------------------------------------</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>via: https://www.linuxforum.com/threads/partition-backup.3638/</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>作者：[Jarret][a]</span></span>\n<span class="line"><span>譯者：[ictlyh](https://github.com/ictlyh)</span></span>\n<span class="line"><span>校對：[jasminepeng](https://github.com/jasminepeng)</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>本文由 [LCTT](https://github.com/LCTT/TranslateProject) 原創編譯，[Linux中國](https://linux.cn/) 榮譽推出</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>[a]:https://www.linuxforum.com/members/jarret.268/</span></span></code></pre></div>',13)])])}const m=n(e,[["render",i]]);export{h as __pageData,m as default};
